import type { MetadataRoute } from "next";

/**
 * PWA manifest — makes AeroTrack installable on Android (Chrome install
 * prompt), desktop and iOS (Add to Home Screen). Icons live in
 * public/icons/ and are generated by scripts/gen-pwa-icons.mjs.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "AeroTrack Pro — Fleet Tracking",
    short_name: "AeroTrack",
    description:
      "Live GPS tracking, trip history, geofences and fleet management — install AeroTrack Pro on your phone or laptop.",
    start_url: "/dashboard",
    scope: "/",
    display: "standalone",
    orientation: "any",
    background_color: "#0d1226",
    theme_color: "#1E40FF",
    categories: ["business", "productivity", "navigation"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    shortcuts: [
      {
        name: "Live Tracking",
        short_name: "Tracking",
        url: "/tracking",
        icons: [{ src: "/icons/icon-192.png", sizes: "192x192" }],
      },
      {
        name: "Get the app",
        short_name: "Download",
        url: "/download",
        icons: [{ src: "/icons/icon-192.png", sizes: "192x192" }],
      },
    ],
  };
}
